    public static void MutaoRealEffectiveHandPileRandomRingAndCold()
    {
        var(g,r)=Start("ring");var hand=V(g,0).Hand.Select(c=>c.Id).ToArray();MutaoUse(g,0);Reach(g,()=>P(g)?.SkillPrompt?.SkillId==StoreWatch);var f=Own(g);var frozen=f.BaoXin!;
        Need(frozen.Original.Select(c=>c.CardId).SequenceEqual(hand)&&frozen.Original.All(c=>c.From==CardLocation.Hand(0))&&E<BaoXinMutaoGiftEvent>(g).Length==0&&V(g,0).HandCount==0,"The whole true original Slash Hand is staged before a single gift, with no invented partial discard.");
        Need(Enumerable.Range(0,4).All(s=>PublicPile(g,s,0).Order().SequenceEqual(hand.Order()))&&Enumerable.Range(1,3).All(s=>g.CreateSnapshot(s).PendingDecision is null),"Every viewer sees the real holder's public stored physical set while the movement child's private choice stays private.");Frozen(frozen.Original);g=Cold(g,r);Continue(g);Reach(g,()=>P(g)?.SkillPrompt?.SkillId==GiftWatch);Need(E<BaoXinMutaoGiftEvent>(g).Length==4,"The first own gain child occurs only after the genuine four-seat wrap, including the original holder.");g=Cold(g,r);Continue(g);Play(g);
        var gifts=E<BaoXinMutaoGiftEvent>(g);Need(gifts.Length==hand.Length&&gifts.Select(e=>e.Recipient).SequenceEqual(Enumerable.Range(1,hand.Length).Select(n=>n%4))&&gifts.Select(e=>e.CardId).Distinct().Count()==hand.Length&&gifts.All(e=>hand.Contains(e.CardId))&&E<BaoXinCompletedEvent>(g).Count(e=>e.FrameId==f.Id)==1,"All exact originals are randomized once each, delivered in the true living ring, and return once without replaying a gift.");
        Need(E<BaoXinRandomIssuedEvent>(g).Where(e=>e.FrameId==f.Id).Count()==hand.Length&&E<BaoXinRandomIssuedEvent>(g).Where(e=>e.FrameId==f.Id).All(e=>e.Before!=e.After&&e.CandidateCount==hand.Length-e.Ordinal+1)&&!g.GetHumanLegalActions().Any(a=>a.SkillId==Mutao)&&PublicPile(g,0,0).Length==0,"Each step has one real PRNG reservation and a shrinking original roster; the actual Play allowance and temporary source finish normally.");_=Cold(g,r);
