    }
    private static PlayerSnapshot V(GameEngine g,int s)=>g.CreateSnapshot(s).Players[s];
    private static bool Has(GameEngine g,int s,string skill)=>V(g,s).Skills!.Any(x=>x.Id==skill);
    private static T[] E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>().ToArray();
    private static PendingDecision? P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
    private static ProgramSkillFrame Own(GameEngine g)=>g.ResolutionStack.OfType<ProgramSkillFrame>().Single(f=>f.BaoXin is not null);
    private static int[] PublicPile(GameEngine g,int viewer,int holder){var p=g.CreateSnapshot(viewer).Players[holder];return p.PublicPersistentPiles is{}piles?piles.Where(x=>x.SourceSkillId==Mutao).SelectMany(x=>x.Cards).Select(c=>c.Id).ToArray():p.PublicPersistentPileSkillId==Mutao?p.PublicPersistentPileCards?.Select(c=>c.Id).ToArray()??[]:[];}
    private static bool Branch(GameEngine g,string b)=>P(g)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="bao-xin"&&c.Parameters.GetValueOrDefault("branch")==b)==true;
    private static bool Offer(GameEngine g,string s)=>P(g)is{PlayerSeat:0}p&&p.SkillPrompt?.SkillId==s&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
    private static void Need(bool ok,string why){if(!ok)throw new InvalidOperationException(Scene+": "+why);}
    private static void Accept(GameEngine g,GameCommand command){try{var result=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([command])).Single());Need(result.Accepted,result.Error?.Message??"Rejected Bao Xin command.");}catch(Exception ex){throw new InvalidOperationException(command.GetType().Name+" cause="+ex.GetType().Name+": "+ex.Message+" "+Diagnostic(g),ex);}}
    private static void Answer(GameEngine g,Func<PromptChoice,bool> test){var p=P(g)!;var c=p.Choices.FirstOrDefault(test);Need(p.PlayerSeat==0&&c is not null,"Missing real human choice "+Diagnostic(g));Accept(g,new AnswerPromptCommand(0,p.PromptId,c!.Id,g.Revision));}
    private static void Choose(GameEngine g,string b,int? card=null,int? seat=null)=>Answer(g,c=>c.Parameters.GetValueOrDefault("branch")==b&&(card is null||c.Cards.SequenceEqual([card.Value]))&&(seat is null||c.Targets.SequenceEqual([seat.Value])));
    private static void Activate(GameEngine g,string s){Reach(g,()=>Offer(g,s));Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");}
    private static void Continue(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("option-id")=="continue");
    private static void Use(GameEngine g,string id,int[]? seats=null,int[]? cards=null)=>Accept(g,new UseProgramSkillCommand(0,Driver,id,cards??[],seats??[],g.Revision,P(g)!.PromptId));
    private static void MutaoUse(GameEngine g,int holder)=>Accept(g,new UseProgramSkillCommand(0,Mutao,"public-slash-ring",[],[holder],g.Revision,P(g)!.PromptId));
    private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
    private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
    private static void TrimTo(GameEngine g,int[] keep){var ids=V(g,0).Hand.Where(c=>!keep.Contains(c.Id)).Select(c=>c.Id).ToArray();if(ids.Length>0){Use(g,"trim",cards:ids);Play(g);}}
    private static void Reach(GameEngine g,Func<bool> done,[CallerMemberName]string method="",[CallerLineNumber]int line=0)
    {
        for(var i=0;i<380;i++)
        {
            if(done())return;Need(g.State.Winner==Winner.None,$"Unexpected completion {method}:{line} "+Diagnostic(g));var p=P(g);
            if(p is null||p.PlayerSeat!=0)Accept(g,new AdvanceOneStepCommand(g.Revision));else if(p.Kind==DecisionKind.PlayCard)End(g);
            else if(p.SkillPrompt?.SkillId is StoreWatch or GiftWatch or PaidWatch or DistanceWatch)Continue(g);
            else if(p.Kind is DecisionKind.RespondDodge or DecisionKind.RespondSlash or DecisionKind.Nullification)Answer(g,c=>c.Cards.Count==0);
            else if(p.Kind==DecisionKind.RescueDying)Answer(g,c=>c.Parameters.GetValueOrDefault("response")is"let-die"or"pass");
            else if(p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");
            else throw new InvalidOperationException($"Unexpected prompt {method}:{line} "+Diagnostic(g));
        }
        throw new InvalidOperationException($"Missing boundary {method}:{line} "+Diagnostic(g));
    }
    private static void Frozen<T>(IReadOnlyList<T> list){var rejected=false;try{((IList<T>)list)[0]=list[0];}catch(NotSupportedException){rejected=true;}Need(rejected,"The owning original material collection refuses external mutation.");}
    private static string Diagnostic(GameEngine g)=>JsonSerializer.Serialize(new{Scene,g.State.TurnNumber,g.State.CurrentSeat,g.State.Winner,Prompt=P(g)is{}p?new{p.Kind,p.PlayerSeat,Skill=p.SkillPrompt?.SkillId,Choices=p.Choices.Take(4).Select(c=>new{c.Cards,c.Targets,c.Parameters})}:null,Frames=g.ResolutionStack.TakeLast(6).Select(f=>new{f.Id,Type=f.GetType().Name,Stage=(f as ProgramSkillFrame)?.BaoXin?.Stage}),Facts=g.Events.TakeLast(4).Select(e=>e.Payload.ToString())});
    private static string State(GameEngine g)=>JsonSerializer.Serialize(new{Views=Enumerable.Range(0,4).Select(s=>SnapshotJson.Serialize(g.CreateSnapshot(s))),Frames=g.ResolutionStack.Select(f=>JsonSerializer.Serialize(f,f.GetType())),g.CardMovements,Zones=g.CreateCardZoneDiagnostics(),Events=g.Events.Select(e=>JsonSerializer.Serialize(e.Payload,e.Payload.GetType())),Commands=CommandJson.Serialize(g.AcceptedCommands)});
    private static GameEngine Cold(GameEngine g,ContentRegistry r){var copy=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(copy),"Cold replay preserves the public original pile, private victim drafts, PRNG reservation, distance snapshot, native damage source and once-paid child return.");return copy;}
